QUESTÃO 16
hŵĂ ƉŝůŚĂ Ġ ƵŵĂ ĞƐƚƌƵƚƵƌĂ ĚĞ ĚĂĚŽƐ ƋƵĞ ĂƌŵĂǌĞŶĂ 
ƵŵĂ ĐŽůĞĕĆŽ ĚĞ ŝƚĞŶƐ ĚĞ ĚĂĚŽƐ ƌĞůĂĐŝŽŶĂĚŽƐ Ğ ƋƵĞ 
ŐĂƌĂŶƚĞ Ž ƐĞŐƵŝŶƚĞ ĨƵŶĐŝŽŶĂŵĞŶƚŽ͗  Ž ƷůƟŵŽ ĞůĞŵĞŶƚŽ 
Ă ƐĞƌ ŝŶƐĞƌŝĚŽ Ġ Ž ƉƌŝŵĞŝƌŽ Ă ƐĞƌ ƌĞŵŽǀŝĚŽ͘   ĐŽŵƵŵ 
ŶĂ  ůŝƚĞƌĂƚƵƌĂ  ƵƟůŝǌĂƌ  ŽƐ  ŶŽŵĞƐ  push e pop  ƉĂƌĂ  ĂƐ 
ŽƉĞƌĂĕƁĞƐ ĚĞ ŝŶƐĞƌĕĆŽ Ğ ƌĞŵŽĕĆŽ ĚĞ Ƶŵ ĞůĞŵĞŶƚŽ 
Ğŵ ƵŵĂ ƉŝůŚĂ͕  ƌĞƐƉĞĐƟǀĂŵĞŶƚĞ͘  K ƐĞŐƵŝŶƚĞ ƚƌĞĐŚŽ 
ĚĞ ĐſĚŝŐŽ Ğŵ ůŝŶŐƵĂŐĞŵ I ĚĞĮŶĞ ƵŵĂ ĞƐƚƌƵƚƵƌĂ ĚĞ 
ĚĂĚŽƐ  ƉŝůŚĂ  ƵƟůŝǌĂŶĚŽ  Ƶŵ  ǀĞƚŽƌ  ĚĞ  ŝŶƚĞŝƌŽƐ͕   ďĞŵ 
ĐŽŵŽ ĂůŐƵŵĂƐ ĨƵŶĕƁĞƐ ƉĂƌĂ ƐƵĂ ŵĂŶŝƉƵůĂĕĆŽ͘
#include <stdlib.h>
#include <stdio.h>
typedef struct {
      int elementos[100];
      int topo;
}pilha;
pilha * cria_pilha() {
      pilha * p =malloc(sizeof(pilha));
      p->topo = -1;
      return pilha;
}
void push(pilha *p, int elemento) {
      if (p->topo >= 99)
 return;
      p->elementos[++p->topo] = elemento;
}
int pop(pilha *p) {
      int a = p->elementos[p->topo];
      p->topo--;
      return a;
}

K ƉƌŽŐƌĂŵĂ Ă ƐĞŐƵŝƌ ƵƟůŝǌĂ ƵŵĂ ƉŝůŚĂ͘
int main() {
      pilha * p = cria_pilha();
      push(p, 2);
      push(p, 3);
      push(p, 4);
      pop(p);
      push(p, 2);
      int a = pop(p) + pop(p);
      push(p, a);
      a += pop(p);
      printf(“%d”, a);
      return 0;
}
  ĞƐƐĞ ƌĞƐƉĞŝƚŽ͕  ĂǀĂůŝĞ ĂƐ ĂĮƌŵĂĕƁĞƐ Ă ƐĞŐƵŝƌ͘
